'use client';

import * as React from 'react';
import { Slider as BaseSlider } from '@base-ui/react/slider';
import { Well } from '../well/well';
import './slider.css';

/* ─────────────────────────────────────────────────────────
 * SLIDER on Base UI Slider
 *
 *   track    a 10 tall well (the track well)
 *   fill     the green intent fill up to the knob
 *   marks    short tick marks along the track (moments, events)
 *   ticks    labelled ticks under the track
 *   knob     a knurled, anodized knob; arrows step, Shift steps large
 *   motion   a jump (a click, a key) rides the part spring; a drag follows the pointer exactly
 * Slots: Slider.Root, Slider.Track, Slider.Marks, Slider.Ticks, Slider.Knob.
 * ───────────────────────────────────────────────────────── */

export interface SliderRootProps {
  value: number;
  min: number;
  max: number;
  step?: number;
  largeStep?: number;
  onValueChange: (value: number) => void;
  className?: string;
  children: React.ReactNode;
}

function Root({ value, min, max, step, largeStep, onValueChange, className, children }: SliderRootProps) {
  return (
    <BaseSlider.Root value={value} min={min} max={max} step={step} largeStep={largeStep} onValueChange={(v) => onValueChange(v as number)} className={className ? `mu-slider ${className}` : 'mu-slider'}>
      <BaseSlider.Control className="mu-slider-control">{children}</BaseSlider.Control>
    </BaseSlider.Root>
  );
}

/** The track well and its fill. */
function Track() {
  return (
    <BaseSlider.Track render={<Well variant="track" radius="pill" />} className="mu-slider-track">
      <BaseSlider.Indicator className="mu-slider-fill" />
    </BaseSlider.Track>
  );
}

/** Tick marks along the track, at fractions 0…1. */
function Marks({ at }: { at: number[] }) {
  return (
    <div className="mu-slider-marks" aria-hidden>
      {at.map((f, i) => (
        <i key={i} style={{ left: `${(f * 100).toFixed(2)}%` }} />
      ))}
    </div>
  );
}

/** Labelled ticks under the track: { at: 0…1, label }. The label is the caller's (a Label). */
function Ticks({ ticks }: { ticks: { at: number; label: React.ReactNode }[] }) {
  return (
    <div className="mu-slider-ticks" aria-hidden>
      {ticks.map((t, i) => (
        <span key={i} style={{ left: `${(t.at * 100).toFixed(2)}%` }}>
          {t.label}
        </span>
      ))}
    </div>
  );
}

function Knob(props: { 'aria-label': string; getAriaValueText?: (formatted: string, value: number, index: number) => string }) {
  return <BaseSlider.Thumb className="mu-slider-knob" {...props} />;
}

export const Slider = Object.assign(Root, { Root, Track, Marks, Ticks, Knob });

@import "../tokens.css";
@import "../well/well.css";

/* Slider. Its look is the slider recipe (--mu-r-slider-*) on the track well. The root fills its box;
   the host sets the box (the track sits on the root's centre line). */
.mu-slider, .mu-slider-control { position: relative; width: 100%; height: 100%; touch-action: none; }
.mu-slider-control { cursor: pointer; }
.mu-slider-track {
  position: absolute;
  left: var(--mu-zero);
  right: var(--mu-zero);
  top: calc(50% - var(--mu-r-slider-track-height) / 2);
  height: var(--mu-r-slider-track-height);
}
.mu-slider-fill {
  height: 100%;
  border-radius: var(--mu-radius-pill);
  background: var(--mu-r-slider-fill-background);
  opacity: var(--mu-r-slider-fill-opacity);
}
.mu-slider-marks, .mu-slider-ticks { position: absolute; left: var(--mu-r-slider-track-inset); right: var(--mu-r-slider-track-inset); pointer-events: none; }
.mu-slider-marks { top: calc(50% - var(--mu-r-slider-mark-h) / 2); height: var(--mu-r-slider-mark-h); }
.mu-slider-marks > i {
  position: absolute;
  width: var(--mu-r-slider-mark-w);
  height: var(--mu-r-slider-mark-h);
  /* From its moment rightwards, as the reference draws it (not centred on it). */
  border-radius: var(--mu-r-slider-mark-radius);
  background: var(--mu-r-slider-mark-color);
}
.mu-slider-ticks { top: calc(50% + var(--mu-r-slider-tick-top)); }
.mu-slider-ticks > span { position: absolute; transform: translateX(-50%); }
.mu-slider-ticks > span::before {
  content: "";
  position: absolute;
  left: 50%;
  top: calc(var(--mu-zero) - var(--mu-r-slider-tick-lift));
  width: var(--mu-r-slider-tick-w);
  height: var(--mu-r-slider-tick-h);
  background: var(--mu-r-slider-tick-color);
}
.mu-slider-knob {
  top: 50%;
  width: var(--mu-r-slider-knob-size);
  height: var(--mu-r-slider-knob-size);
  border-radius: var(--mu-round);
  cursor: grab;
  background: var(--mu-r-slider-knob-background);
  box-shadow: var(--mu-r-slider-knob-shadow);
}
.mu-slider[data-dragging] .mu-slider-knob { cursor: grabbing; }
.mu-slider-knob:has(:focus-visible) { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }
/* A jump (a click, a key) rides the part spring; a drag follows the pointer exactly. */
.mu-slider:not([data-dragging]) .mu-slider-knob { transition: inset-inline-start var(--mu-spring-part-d) var(--mu-spring-part), left var(--mu-spring-part-d) var(--mu-spring-part); }
.mu-slider:not([data-dragging]) .mu-slider-fill { transition: width var(--mu-spring-part-d) var(--mu-spring-part); }
